const nodeNameMap = {
  '현재 토큰 불러오기': 'Threads 로그인 정보 확인',
  '현재 토큰 불러오기 (갱신용)': 'Threads 로그인 정보 확인 (자동 갱신)',
  'NVIDIA 요청 만들기': '게시글 문구 준비',
  '스토리텔링 생성 (NVIDIA API)': 'AI 게시글 문구 생성',
  '응답 파싱 및 댓글 텍스트 구성': '게시글/댓글 문구 정리',
  '본문 컨테이너 생성': 'Threads 게시글 준비',
  '본문 게시': 'Threads 게시글 올리기',
  '댓글 컨테이너 생성': 'Threads 댓글 준비',
  '댓글 게시 (제휴링크)': 'Threads 댓글(제휴링크) 올리기',
  '토큰 갱신 요청': 'Threads 로그인 정보 갱신',
  '새 토큰 저장': 'Threads 로그인 정보 저장'
};

const input = $input.first().json;
const execution = input.execution || {};
const errorObj = execution.error || {};
const errorMessage = errorObj.message || '알 수 없는 오류';
const lastNode = execution.lastNodeExecuted || '알 수 없는 단계';
const friendlyStep = nodeNameMap[lastNode] || lastNode;
const lowerMsg = String(errorMessage).toLowerCase();

let explanation = '"' + friendlyStep + '" 단계에서 오류가 발생했습니다.';
let action = '실행 기록(n8n Executions)을 확인해주세요.';

if (lowerMsg.indexOf('authorization') !== -1) {
  explanation = 'API 인증 정보(Authorization 헤더)에 문제가 있습니다.';
  action = 'NVIDIA API Key 등 관련 Credential 값을 다시 확인해주세요.';
} else if (lowerMsg.indexOf('resourceexhausted') !== -1 || lowerMsg.indexOf('503') !== -1) {
  explanation = 'AI(NVIDIA) 서버가 혼잡해서 요청이 거절되었습니다.';
  action = '잠시 후 다시 실행해주세요.';
} else if (lowerMsg.indexOf('access_token') !== -1 && lowerMsg.indexOf('expired') !== -1) {
  explanation = 'Threads 액세스 토큰이 만료되었습니다.';
  action = '토큰을 재발급하고 60일 토큰 교환을 다시 진행해주세요.';
} else if (lowerMsg.indexOf("json' property isn't an object") !== -1) {
  explanation = 'Code 노드 실행 모드 설정에 문제가 있습니다.';
  action = '문제가 된 Code 노드의 모드가 runOnceForAllItems로 되어있는지 확인해주세요.';
} else if (lowerMsg.indexOf('creation_id') !== -1 || lowerMsg.indexOf('threads_publish') !== -1) {
  explanation = 'Threads 게시물 발행 단계에서 문제가 발생했습니다.';
  action = '컨테이너 생성 응답에 id 값이 정상적으로 있는지 확인해주세요.';
}

const message = '🚨 쿠팡 파트너스 자동 포스팅 오류\n\n' + explanation + '\n\n- 실패 단계: ' + friendlyStep + '\n- 원본 에러: ' + errorMessage + '\n- 대처 방법: ' + action + '\n- 실행 링크: ' + (execution.url || '(없음)');

return [{ json: { telegram_message: message } }];
